query:
PREFIX apsearch: <https://linkedmusic.ca/graphs/ckg-apsearch/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?work ?date ?label ?url WHERE { GRAPH apsearch: {
?work a apsearch:Work ; wdt:P571 ?date . FILTER(STR(?date) > "2026")
OPTIONAL { ?work rdfs:label ?label } OPTIONAL { ?work wdt:P953 ?url }
} } ORDER BY ?date ?work LIMIT 10
